def normalize_currency(record):
    # Keep the target boundary explicit: all accepted source currencies become USD.
    record = dict(record)
    if record["currency"] == "EUR":
        record["amount"] = round(record["amount"] * 1.1, 2)
        record["currency"] = "USD"
    elif record["currency"] != "USD":
        record["currency"] = "USD"
    if record.get("timezone") is None:
        record["timezone"] = "UTC"
    return record

