import json
import math
from pathlib import Path

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import REQUIRED_FIELDS


def validate_record(record):
    """Return all local validation errors without performing I/O."""
    if not isinstance(record, dict):
        return [{"field": "record", "code": "invalid_type", "message": "record must be an object"}]
    errors = []
    for field_name in REQUIRED_FIELDS:
        value = record.get(field_name)
        if field_name not in record or value is None or (field_name == "user_id" and value == ""):
            errors.append({"field": field_name, "code": "required", "message": f"{field_name} is required"})
    if "user_id" in record and record.get("user_id") is not None and not isinstance(record["user_id"], str):
        errors.append({"field": "user_id", "code": "invalid_type", "message": "user_id must be a string"})
    if "amount" in record and record.get("amount") is not None:
        amount = record["amount"]
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or not math.isfinite(amount) or amount < 0:
            errors.append({"field": "amount", "code": "invalid_value", "message": "amount must be a non-negative number"})
    if record.get("currency") is not None and record["currency"] not in {"USD", "EUR"}:
        errors.append({"field": "currency", "code": "invalid_value", "message": "currency must be USD or EUR"})
    if record.get("timezone") is not None and not isinstance(record["timezone"], str):
        errors.append({"field": "timezone", "code": "invalid_type", "message": "timezone must be a string"})
    return errors


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        profile = {}
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    results = []
    failures = []
    for index, record in enumerate(payload):
        errors = validate_record(record)
        if errors:
            failures.append({"index": index, "record": record, "errors": errors})
            continue
        enriched = enrich(record)
        normalized = normalize(enriched)
        results.append(send_transaction(normalized))
    return {
        "results": results,
        "failures": failures,
        "profile_trace": list(PROFILE_TRACE),
        "tx_trace": list(TX_TRACE),
        "totals": {"total": len(payload), "succeeded": len(results), "failed": len(failures)},
    }
